        rows = self._vector_relations(rel_type)
        match = self._relation_similarity(state, rows, 0)
        if vp is not None:
            match = match * self._relation_similarity(vp, rows, 1)
        result = [(int(row), float(score * self.c_plus[row]), self.slots[row, 1].clone(),
