    object.__setattr__(owner, '_last_occurrence_priming', dict(
        rows=len(set(rows.tolist())), edges=len(pairs),
        activated_competitors=int(((before <= 1) & (surface > 1)).sum()),
        row_energy=row_energy.detach()))
    return surface

