"""One index pairs a perceptual form with a conceptual meaning.

The cached representation is [form | meaning]. Perception reconstruction alone
writes native prototypes and evidence; the sentence read detaches them. Order-zero
meaning is the detached occurrence-context mean. Letters need no conceptual row.
Bootstrap from conceptual wholes is deferred to the operators update.
"""
import torch
from torch import nn
from torch.nn import functional as F


class MereologicalCodes(nn.Module):
    def __init__(self, owner, initial, *, percept_width,
                 percept_event_width):
        super().__init__()
        object.__setattr__(self, 'owner', owner)
        self.percept_width = int(percept_width)
        self.percept_event_width = int(percept_event_width)
        self.code_width = int(initial.shape[-1])
        if not 0 < self.percept_width <= self.percept_event_width <= self.code_width:
            raise ValueError('paired representation must contain the native form block')
        self.context_width = self.code_width - self.percept_event_width
        self._context = None

    @torch.no_grad()
    def occurrence_terms(self):
        """Occurrence membership supplies n and detached conceptual meaning M.

        A reference witnesses membership even in an unverified sentence.
        Its truth poles state a different fact and are never changed here.
        """
        store = self.owner._closed_clause_store()
        if store is None or not len(store):
            return {}
        terms = {}
        now = float(store._next_ts) - 1
        terms = occurrence_memberships(self.owner, store)
        result = {}
        width = self.code_width
        for code, rows in terms.items():
            rows = [r for r in sorted(rows) if int(store.rel_type[r]) == store.REL_NONE]
            if not rows:
                continue
            idx = torch.tensor(rows, dtype=torch.long, device=store.slots.device)
            weight = 1 / (1 + (now-store.timestamp[idx]).clamp_min(0))
            roots = store.slots[idx, 0, :width].detach()
            if roots.shape[-1] < width:
                roots = F.pad(roots, (0, width-roots.shape[-1]))
            roots = roots[:, self.percept_event_width:]
            result[code] = (len(rows), ((roots * weight[:, None]).sum(0) / weight.sum()).detach().clone())
        return result

    def begin_forward(self):
        # Both walk paths use the same pre-forward durable context; the
        # current closing becomes available on the next forward only.
        self._context = self.occurrence_terms()
        from Spaces import _concept_alloc_of
        cb = self.owner.similarity_codebook
        rows = sorted(_concept_alloc_of(self.owner).layer()._tensor_row_keys)
        with torch.no_grad():
            cb.W.zero_()
            if rows:
                cb.lookup_rows(torch.tensor(rows, device=cb.W.device))

    def context_audit(self):
        context = self.occurrence_terms() if self._context is None else self._context
        return [dict(row=row, occurrences=n, context_width=self.context_width,
                     context_norm=float(mean.norm()), bootstrap_learning=False)
                for row, (n, mean) in sorted(context.items())]

    @torch.no_grad()
    def support_audit(self, rows):
        rows = list(map(int, rows))
        codes = self.derive(rows)[..., :self.percept_width].abs()
        records = []
        for row, code in zip(rows, codes):
            nonzero = code != 0
            text = self.owner.word_surface_for_row(row)
            records.append(dict(row=row, word=None if text is None else text.decode('utf8'),
                dimension=self.percept_width, percept_event_width=self.percept_event_width,
                nonzero_coordinates=int(nonzero.sum()),
                nonzero_fraction=int(nonzero.sum())/self.percept_width,
                minimum_absolute_value=float(code.min()),
                minimum_nonzero_absolute_value=(float(code[nonzero].min()) if nonzero.any() else None)))
        return records

    def _native(self, tower):
        model = self.owner._model
        space = model.perceptualSpace if tower == 0 else model.wholeSpace
        return space.subspace.what

    @torch.no_grad()
    def _definitions(self, rows):
        """Net 11b evidence per native part/property, never the both corner."""
        from Spaces import _concept_alloc_of
        layer = _concept_alloc_of(self.owner).layer()
        definitions = {int(row): {} for row in rows}
        for (row, column), pos in layer.features._index.items():
            if row not in definitions:
                continue
            tower, pole = (column // 2) % 2, column % 2
            group = layer.feature_groups.get((row, column), (column // 4,))
            for pid in dict.fromkeys(group):
                poles = definitions[row].setdefault((tower, pid), [0., 0.])
                poles[pole] += float(layer.features.values[pos].detach())
        return {row: [(tower, pid, max(0., poles[0]-poles[1]))
                       for (tower, pid), poles in sorted(edges.items())]
                for row, edges in definitions.items()}

    @torch.no_grad()
    def _interval(self, edges):
        like = self.owner.similarity_codebook.W
        bounds, weights, extrema, ids = [], [], [], []
        for tower in (0, 1):
            selected = [(pid, d) for t, pid, d in edges if t == tower and d > 0]
            ids.append([pid for pid, _ in selected])
            if not selected:
                bounds.append(like.new_full((self.percept_width,), float(tower)))
                weights.append(0.)
                extrema.append(None)
                continue
            codes = self._native(tower).lookup_rows(torch.tensor(ids[-1], device=like.device)).detach()
            if codes.shape[-1] != self.percept_width:
                raise RuntimeError('native towers must share the form coordinates')
            d = like.new_tensor([d for _, d in selected])
            values = codes if tower == 0 else 1-d[:, None]*(1-codes)
            bound, extreme = values.max(0) if tower == 0 else values.min(0)
            bounds.append(bound); weights.append(float(d.sum())); extrema.append(extreme)
        return bounds, weights, extrema, ids

    @torch.no_grad()
    def containment_audit(self, *, before=None, after=None):
        """Audit order-zero form containment through positive-part postings.

        Optional row-to-form snapshots expose both sides of the future centroid
        placement pass. This observer does not project or change any code.
        Equal part sets are checked in both directions; self pairs are omitted.
        """
        from Spaces import _concept_alloc_of
        rows = sorted(row for row in _concept_alloc_of(self.owner).layer()._tensor_row_keys
                      if self.owner._order0_inventory_row(row))
        parts = {row: {pid for tower, pid, net in edges if tower == 0 and net > 0}
                 for row, edges in self._definitions(rows).items()}
        postings = {}
        for row, members in parts.items():
            for pid in members:
                postings.setdefault(pid, set()).add(row)
        pairs = []
        for row, members in parts.items():
            extents = sorted((postings[pid] for pid in members), key=len)
            containers = set.intersection(*extents) if extents else set(rows)
            pairs.extend((row, other) for other in sorted(containers) if row != other)
        values = dict(zip(rows, self.derive(rows)[..., :self.percept_width]))
        def report(snapshot):
            snapshot = values if snapshot is None else snapshot
            count = coordinates = 0
            largest = 0.
            for contained, container in pairs:
                violation = (snapshot[contained][:self.percept_width]-
                             snapshot[container][:self.percept_width]).clamp_min(0)
                positive = int(violation.gt(0).sum())
                count += int(positive > 0)
                coordinates += positive
                largest = max(largest, float(violation.max()))
            return dict(pairs=len(pairs), violating_pairs=count,
                        coordinates=coordinates, largest=largest)
        return dict(order=0, rows=len(rows), postings=len(postings),
                    self_pairs=False, before=report(before), after=report(after))

    @torch.no_grad()
    def room_report(self, margin=0.):
        from Spaces import _concept_alloc_of
        rows = sorted(_concept_alloc_of(self.owner).layer()._tensor_row_keys)
        violations = []
        for row, edges in self._definitions(rows).items():
            (lower, upper), _, _, ids = self._interval(edges)
            if ids[0] or ids[1]:
                violations.append((lower-upper+float(margin)).relu())
        values = torch.cat(violations) if violations else self.owner.similarity_codebook.W.new_zeros(0)
        return dict(count=int((values > 0).sum()),
                    largest=float(values.max()) if values.numel() else 0.)

    @torch.no_grad()
    def project_room(self, margin=0.):
        """One deterministic pass over concept/coordinate; no loss or gradient.

        Only the minimal whole moves, by the full violation. Parts never
        shrink to fit their types. Report any residual after evidence/clipping.
        """
        from Spaces import _concept_alloc_of
        before = self.room_report(margin)
        rows = sorted(_concept_alloc_of(self.owner).layer()._tensor_row_keys)
        for row, edges in self._definitions(rows).items():
            (lower, upper), _, extrema, ids = self._interval(edges)
            if not (ids[0] or ids[1]):
                continue
            violation = (lower-upper+float(margin)).relu()
            for coordinate in (violation > 0).nonzero().flatten().tolist():
                if not ids[1]:
                    continue  # the absent whole is the fixed upper boundary 1
                pid = ids[1][int(extrema[1][coordinate])]
                value = self._native(1).W[pid, coordinate]
                value.copy_((value.clamp(0, 1)+violation[coordinate]).clamp(0, 1))
        report = dict(margin=float(margin), before=before, after=self.room_report(margin))
        self.last_room_projection = report
        return report

    @torch.no_grad()
    def derive(self, indices):
        owner = self.owner
        cached = owner.similarity_codebook.W
        indices = torch.as_tensor(indices, dtype=torch.long, device=cached.device)
        shape = indices.shape
        requested = indices.flatten().cpu().tolist()
        unique = list(dict.fromkeys(requested))
        row_index = {row: i for i, row in enumerate(unique)}
        out = cached.new_zeros(len(unique), self.code_width)
        for row, edges in self._definitions(unique).items():
            if not edges:
                continue  # an unallocated cache row has neither form nor meaning
            (lower, _upper), _, _, _ = self._interval(edges)
            out[row_index[row], :self.percept_width] = lower
        model = getattr(owner, '_model', None)
        identity = getattr(getattr(getattr(model, 'perceptualSpace', None), 'percept_store', None), 'identity', None)
        if identity is not None:
            for row in unique:
                raw = owner.word_surface_for_row(row)
                if raw in identity.words:
                    # Identification is immutable. Learned support changes a
                    # reading's evidence, never the named word's sparse key.
                    out[row_index[row], :identity.width] = identity.form(raw).to(out)
        context = self.occurrence_terms() if self._context is None else self._context
        for row in unique:
            if row in context and self.context_width:
                out[row_index[row], self.percept_event_width:] = context[row][1].detach().to(out)
        result = out[torch.tensor([row_index[r] for r in requested], device=out.device, dtype=torch.long)]
        return result.reshape(*shape, self.code_width)


@torch.no_grad()
def occurrence_memberships(owner, store):
    """Use both native slot references and the durable leaf-code postings."""
    terms = {}
    for (code, _role), rows in store._leaf_postings.items():
        terms.setdefault(int(code), set()).update(rows)
    for row, references in enumerate(store.refs[:len(store)].tolist()):
        if int(store.rel_type[row]) == store.REL_DEF:
            continue
        for cid in set(references):
            code = owner._csw_row_of(cid) if cid > 0 else None
            if code is None and cid > 0:
                definitions = owner._definition_index()
                objects = () if definitions is None else definitions.objects(cid)
                code = owner._csw_row_of(objects[0]) if len(objects) == 1 else None
            if code is not None:
                terms.setdefault(int(code), set()).add(row)
    return terms


@torch.no_grad()
def conduct_occurrences(owner, surface, *, active_rows=None):
    """Two hops, word → existing row → constituents, conserving energy."""
    store = owner._closed_clause_store()
    spread = float(getattr(owner, '_priming_spread', 0.) or 0.)
    if store is None or not len(store) or spread <= 0:
        return surface
    B, V = surface.shape
    active = torch.ones(B, dtype=torch.bool, device=surface.device) if active_rows is None else active_rows.to(surface.device)
    pairs = sorted({(int(code), int(row)) for code, rows in occurrence_memberships(owner, store).items()
                    if 0 <= code < V for row in rows if int(store.rel_type[row]) != store.REL_DEF})
    if not pairs:
        return surface
    words, rows = torch.tensor(pairs, device=surface.device, dtype=torch.long).T
    recency = 1 / (1 + (float(store._next_ts)-1-store.timestamp[rows]).clamp_min(0)).to(surface)
    degree = surface.new_zeros(V).index_add_(0, words, recency)
    flow = spread * (surface[:, words]-1) * recency / degree[words]
    flow *= active[:, None]
    row_energy = surface.new_zeros(B, len(store)).index_add_(1, rows, flow)
    # A row's constituents inherit the energy it received. Using the same
    # incidence set makes both hops explicit and avoids a word-code attraction.
    row_degree = surface.new_zeros(len(store)).index_add_(0, rows, recency)
    returning = row_energy[:, rows] * recency / row_degree[rows]
    before = surface.clone()
    surface.index_add_(1, words, -flow)
    surface.index_add_(1, words, returning)
    surface.clamp_min_(0.)
    object.__setattr__(owner, '_last_occurrence_priming', dict(
        rows=len(set(rows.tolist())), edges=len(pairs),
        activated_competitors=int(((before <= 1) & (surface > 1)).sum()),
        row_energy=row_energy.detach()))
    return surface

bin/WordIdentity.py.new:
"""Rung-zero identity: boundary pairs, exact length parts, collision mints.

Atom rows and word rows belong to the existing RadixLayer. Their codes are
fixed functions of atom bytes, not parameters. Only a recorded collision
may extend a minted atom's deterministic bit stream. Binding uses a separate
fixed dense view; indexes and reconstruction retain the sparse form.
"""
import hashlib
from functools import lru_cache

import numpy as np
import torch
from torch import nn
from torch.nn import functional as F


def resolve_identity_layout(config):
    """Resolve text form storage before constructing any spaces.

    Older XML files described a learned letter width. Identity now owns an
    explicit pair width plus 32 length bits. Preserve the declared meaning
    complement and live slot/row counts; numeric configurations are untouched.
    """
    from architecture import canonical_shape
    arch = config.get('architecture', {})
    if arch.get('data', {}).get('dataType', arch.get('dataType')) != 'embedding':
        return
    ps = config.setdefault('PartSpace', {})
    if not ps.get('identityByParts', True):
        return
    pair = int(ps.setdefault('identityPairDim', 64))
    ones = int(ps.setdefault('identityOnes', 3))
    length = int(ps.setdefault('identityLengthDim', 32))
    dense = int(ps.setdefault('identityBindingDim', 64))
    if pair < ones or ones < 1 or length != 32 or dense < 1:
        raise ValueError('identity requires D >= s > 0, L = 32 and a positive binding width')
    width = pair + length
    if dense > width:
        raise ValueError('binding width must fit the reserved form block')
    old_ps = int(ps.get('nDim', 0))
    old_cs = int(config.get('ConceptualSpace', {}).get('nDim', old_ps)) or old_ps
    form_event = width + sum(canonical_shape('PartSpace'))
    complement = max(0, old_cs - old_ps)
    # Recurrent WS and the output head consume CS events, not their own
    # native form width. Retain deliberately inconsistent declarations so
    # normal configuration validation still rejects them.
    for section in ('WholeSpace', 'OutputSpace'):
        item = config.get(section, {})
        if int(item.get('nInputDim', 0) or 0) == old_cs and old_cs > 0:
            item['nInputDim'] = form_event + complement
    for section, event in (('InputSpace', form_event), ('PartSpace', form_event),
                           ('WholeSpace', form_event),
                           ('ConceptualSpace', form_event + complement)):
        item = config.setdefault(section, {})
        old = int(item.get('nDim', 0))
        item['nDim'] = event
        for key in ('nInputDim', 'nOutputDim'):
            if int(item.get(key, 0) or 0) == old and old > 0:
                item[key] = event


def text_of(raw):
    return bytes(raw).decode('utf8', 'surrogateescape')


def bytes_of(text):
    return text.encode('utf8', 'surrogateescape')


@lru_cache(maxsize=16384)
def bit_stream(atom, dimension):
    seed = int.from_bytes(hashlib.sha256(atom).digest()[:8], 'little')
    return tuple(map(int, np.random.default_rng(seed).permutation(dimension)))


def base_atoms(raw):
    word = text_of(raw)
    marked = '#' + word + '#'
    return tuple(dict.fromkeys(
        [('pair', marked[i:i+2]) for i in range(len(marked)-1)] +
        [('length', str(i)) for i in range(1, len(word)+1)]))


class WordIdentity(nn.Module):
    PREFIX = b'\x00identity/atom/'
    WORD_PREFIX = b'\x00identity/form/'

    def __init__(self, store, pair_dim=64, ones=3, length_dim=32, binding_dim=64):
        super().__init__()
        object.__setattr__(self, 'store', store)
        self.pair_dim, self.ones = int(pair_dim), int(ones)
        self.length_dim, self.binding_dim = int(length_dim), int(binding_dim)
        self.width = self.pair_dim + self.length_dim
        if store.dim != self.width or not 0 < self.ones <= self.pair_dim:
            raise ValueError('Radix identity bank width must be D + L, with 0 < s <= D')
        seed = int.from_bytes(hashlib.sha256(b'word-identity-projection-v1').digest()[:8], 'little')
        # A local generator cannot move any training's initialization stream.
        matrix = np.random.default_rng(seed).normal(size=(self.width, self.binding_dim))
        self.register_buffer('projection', torch.tensor(matrix / self.binding_dim**.5, dtype=torch.float32))
        self.atoms, self.bits, self.words, self.word_rows, self.forms = {}, {}, {}, {}, {}
        self.word_keys = {}
        self.mints = []
        self.revision = 0
        basis = store._basis
        if not hasattr(basis, 'fixed_row_mask'):
            basis.register_buffer('fixed_row_mask', torch.zeros(store._capacity, dtype=torch.bool, device=basis.W.device))
            basis.register_buffer('fixed_row_codes', torch.zeros_like(basis.W, requires_grad=False))

    def atom_code(self, atom, bits=None):
        kind, value = atom
        result = torch.zeros(self.width)
        if kind == 'length':
            k = int(value)
            if k <= self.length_dim:
                result[self.pair_dim+k-1] = 1
        else:
            n = self.bits.get(atom, self.ones) if bits is None else int(bits)
            result[list(bit_stream(bytes_of(value), self.pair_dim)[:n])] = 1
        return result

    @torch.no_grad()
    def _fixed(self, row, value):
        basis = self.store._basis
        value = value.to(basis.W)
        basis.fixed_row_mask[row] = True
        basis.fixed_row_codes[row].copy_(value)
        basis.W[row].copy_(value)

    def _atom(self, atom, bits=None):
        if bits is not None:
            self.bits[atom] = max(self.bits.get(atom, self.ones), int(bits))
        code = self.atom_code(atom)
        if atom not in self.atoms:
            key = self.PREFIX + atom[0].encode() + b'/' + bytes_of(atom[1])
            self.atoms[atom] = self.store.insert(key, init_vector=code)
        self._fixed(self.atoms[atom], code)
        return self.atoms[atom]

    def form(self, raw):
        atoms = self.words.get(bytes(raw), base_atoms(raw))
        return torch.stack([self.atom_code(a) for a in atoms]).amax(0)

    @staticmethod
    def key(form):
        return np.packbits(form.detach().cpu().numpy().astype(np.uint8), bitorder='little').tobytes()

    def _mint(self, left, right):
        a, b = '#' + text_of(left) + '#', '#' + text_of(right) + '#'
        old_a, old_b = self.form(left), self.form(right)
        positions = [pos for pos in range(max(len(a),len(b))-2)
                     if len(a[pos:pos+3]) == len(b[pos:pos+3]) == 3
                     and a[pos:pos+3] != b[pos:pos+3]]
        # Exhaust the differing triple positions, then try quadruples at
        # those positions. Unsuccessful proposals never alter stored atoms.
        for size in (3, 4):
            for pos in positions:
                x, y = a[pos:pos+size], b[pos:pos+size]
                if len(x) != size or len(y) != size or x == y:
                    continue
                aa, bb = ('mint', f'{x}@{pos}'), ('mint', f'{y}@{pos}')
                for bits in range(max(self.bits.get(aa, self.ones), self.bits.get(bb, self.ones)), self.pair_dim+1):
                    ca, cb = self.atom_code(aa, bits), self.atom_code(bb, bits)
                    if not torch.equal(torch.maximum(old_a, ca), torch.maximum(old_b, cb)):
                        self._atom(aa, bits); self._atom(bb, bits)
                        self.words[left] = tuple(dict.fromkeys((*self.words[left], aa)))
                        self.words[right] = tuple(dict.fromkeys((*self.words[right], bb)))
                        self.mints.append(dict(words=[text_of(left), text_of(right)],
                            atoms=[aa[1], bb[1]], bit_counts=[bits, bits], size=size, position=pos))
                        self.revision += 1
                        return
        raise ValueError(f'identity mint exhausted triples and quadruples: {left!r}, {right!r}')

    def _reindex(self):
        self.forms = {}
        self.word_keys = {}
        for raw in self.words:
            key = self.key(self.form(raw))
            if key in self.forms and self.forms[key] != raw:
                return self.forms[key], raw
            self.forms[key] = raw
            self.word_keys[raw] = key
        return None

    def admit(self, raw):
        raw = bytes(raw)
        if not raw:
            raise ValueError('a word identity requires nonempty bytes')
        if raw not in self.words:
            self.words[raw] = base_atoms(raw)
            for atom in self.words[raw]:
                self._atom(atom)
            pending, affected = [raw], {raw}
            while pending:
                word = pending.pop()
                key = self.key(self.form(word))
                other = self.forms.get(key)
                if other is not None and other != word:
                    self._mint(other, word)
                    changed = set(self.words[other][-1:]) | set(self.words[word][-1:])
                    touched = {w for w, parts in self.words.items() if changed.intersection(parts)}
                    affected.update(touched)
                    for w in touched:
                        old = self.word_keys.pop(w, None)
                        if old is not None and self.forms.get(old) == w:
                            del self.forms[old]
                            self.store.hash_map.pop(self.WORD_PREFIX+old, None)
                    pending.extend(touched)
                else:
                    self.forms[key] = word
                    self.word_keys[word] = key
            # Rekey the affected old words too; their row addresses are stable.
            for word in sorted(affected):
                value = self.form(word)
                key = self.WORD_PREFIX + self.key(value)
                row = self.word_rows.get(word)
                if row is None:
                    row = self.store.insert(key, init_vector=value)
                    self.word_rows[word] = row
                    self.store.inverse_table[row] = word
                    # Keep byte rows distinct for one-letter words/descent.
                    if len(word) > 1:
                        self.store.hash_map[word] = row
                        self.store.radix_trie.insert(word, row)
                self._fixed(row, value)
                self.store.hash_map[key] = row
                self.store.radix_trie.insert(key, row)
        return tuple(self.atoms[a] for a in self.words[raw])

    def row_for_form(self, form):
        raw = self.forms.get(self.key(form))
        return None if raw is None else self.word_rows[raw]

    def read(self, form):
        row = self.row_for_form(form)
        return None if row is None else self.store.bytes_for(row)

    def read_parts(self, rows, *, form=None):
        """Read an indexed identity, or assemble an unindexed pair spelling."""
        atoms = {row: atom for atom, row in self.atoms.items()}
        parts = [atoms[int(row)] for row in rows]
        if form is None:
            form = torch.stack([self.atom_code(atom) for atom in parts]).amax(0)
        known = self.read(form)
        if known is not None:
            return known
        lengths = [int(value) for kind, value in parts if kind == 'length']
        if not lengths:
            raise ValueError('pair reconstruction requires cumulative length parts')
        return assemble_pairs([value for kind, value in parts if kind == 'pair'],
                              max(lengths), index=self, form=form)

    def binding(self, atoms):
        """Preserve the event/meaning layout while changing only code direction."""
        projected = atoms[..., :self.width] @ self.projection.to(atoms)
        return torch.cat((F.pad(projected, (0, self.width-self.binding_dim)),
                          atoms[..., self.width:]), -1)

    def vocab_extras(self):
        return dict(atoms=self.atoms, bits=self.bits, words=self.words,
                    word_rows=self.word_rows, mints=self.mints, revision=self.revision)

    def load_vocab_extras(self, value):
        for name in ('atoms', 'bits', 'words', 'word_rows', 'mints', 'revision'):
            setattr(self, name, value[name])
        self._reindex()

    def audit(self):
        words = sorted(self.words)
        forms = {w: self.form(w) for w in words}
        postings = {}
        for word in words:
            for atom in self.words[word]:
                postings.setdefault(atom, set()).add(word)
        comparable = []
        for word in words:
            lists = sorted((postings[a] for a in self.words[word]), key=len)
            supersets = lists[0].intersection(*lists[1:])
            comparable.extend((word, other) for other in sorted(supersets) if other != word)
        return dict(vocabulary=[text_of(w) for w in words], pair_dim=self.pair_dim,
            length_dim=self.length_dim, ones=self.ones, binding_dim=self.binding_dim,
            collisions=len(words)-len({self.key(v) for v in forms.values()}),
            containment_pairs=[(text_of(a), text_of(b)) for a, b in comparable],
            containment_violations=sum(bool((forms[a] > forms[b]).any()) for a,b in comparable),
            reconstruction_errors=sum(self.read(forms[w]) != w for w in words), mints=self.mints)


def assemble_pairs(pairs, length, *, index=None, form=None):
    """Assemble an unindexed spelling from its pair set and exact length.

    Pair sets omit multiplicity. Ambiguous sequences require the minted
    identity index; no arbitrary spelling is substituted for an identity.
    """
    if index is not None and form is not None:
        known = index.read(form)
        if known is not None:
            return known
    pairs = set(pairs)
    answers = []
    def walk(text, used):
        if len(answers) > 1:
            return
        if len(text) == length + 1:
            end = text[-1]+'#'
            if end in pairs and used | {end} == pairs:
                answers.append(bytes_of(text[1:]))
            return
        for pair in sorted(pairs):
            if pair[0] == text[-1] and pair[1] != '#':
                walk(text+pair[1], used | {pair})
    walk('#', set())
    if len(answers) != 1:
        raise ValueError('pair/length spelling is unresolved; a minted index identity is required')
    return answers[0]
